contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool flag) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balances before
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: for any input flag, either the call reverted, or C's balance is zero afterwards
        // and this contract's balance did not decrease.
        assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }
    receive() external payable { }
}

