// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool flag) internal {
        vm.deal(address(c), VALUE_CAP);
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
    }

    function testFuzz_run(bool flag) public {
        _run(flag);
    }

    receive() external payable { }
}
